{view==='Assessments'&&<><Heading title="Every submission matters." sub="Review work, refine feedback, and record the next step."><button className="primary" onClick={()=>start('Writing Task 1')}><Plus size={17}/> New assessment</button></Heading><section className="panel"><div className="toolbar"><Tabs value={filter} onValueChange={setFilter}><TabsList>{['All','Writing','Speaking','Listening','Reading'].map(v=><TabsTrigger key={v} value={v}>{v}</TabsTrigger>)}</TabsList></Tabs><div className="search-field"><Search size={17}/><input aria-label="Search assessments" placeholder="Find a student or submission…" value={query} onChange={e=>setQuery(e.target.value)}/></div></div><AssessmentTable items={filtered}/></section></>}
{view==='Band calculator'&&<BandCalculator students={students} assessments={assessments} open={id=>{setView('Assessments');setSelected(id)}}/>}{view==='Progress'&&<><Heading title="See the progress behind the score." sub="Compare like-for-like work and turn patterns into teaching priorities."/><div className="toolbar"><Pick label="Choose student" value={progressStudent} onChange={setProgressStudent} options={students.map(s=>({value:s.id,label:s.name}))}/><Pick label="Task type" value={progressTask} onChange={setProgressTask} options={opts(['Overall',...taskTypes])}/>{progressStudent&&<button className="secondary" onClick={()=>setReportFor(progressStudent)}><Mail size={16}/> Email progress report</button>}</div>{progressStudent&&progressTask==='Overall'?<OverallProgressView student={students.find(s=>s.id===progressStudent)!} items={assessments.filter(a=>a.student_id===progressStudent)} open={id=>{setView('Assessments');setSelected(id)}}/>:progressStudent?<ProgressView student={students.find(s=>s.id===progressStudent)!} items={reviewed.filter(a=>a.student_id===progressStudent&&a.task===progressTask)} task={progressTask} open={id=>{setView('Assessments');setSelected(id)}}/>:<section className="panel"><Empty title="Choose a student to explore progress"><p>Charts use teacher-reviewed assessments of the same task type. AI drafts are excluded until you review them.</p></Empty></section>}</>}
